-- ===================================================
-- migration_089: メーター検査を「2026年メーター管理台帳」に寄せて項目追加
--   登録番号・メーター器NO・前年受検日・検査済票番号・受検日・更新/交換/代替・点検者を追加し、
--   台帳(2026年8班分、297台)の最新受検記録を初期データとして取り込む
-- ===================================================

ALTER TABLE meter_inspections ADD COLUMN registration_no TEXT;      -- 登録番号（例: 板橋510あ5006）
ALTER TABLE meter_inspections ADD COLUMN meter_device_no TEXT;      -- メーター器NO
ALTER TABLE meter_inspections ADD COLUMN prev_inspection_date TEXT; -- 前年受検日
ALTER TABLE meter_inspections ADD COLUMN cert_no TEXT;              -- 検査済票番号
ALTER TABLE meter_inspections ADD COLUMN inspection_date TEXT;      -- 受検日（直近の実施日）
ALTER TABLE meter_inspections ADD COLUMN update_kind TEXT;          -- 'renewal'|'exchange'|'substitute'（更新/交換/代替）
ALTER TABLE meter_inspections ADD COLUMN checker_name TEXT;         -- 点検者

